      "name": "subject_format_fit",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "How well the subject fits the format is largely a property of the subject; it influences both the delivery approach available and satisfaction. Acts as a common cause rather than an educator-set lever."
    },
    {
      "name": "hands_on_criticality",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Whether hands-on work is essential is an intrinsic property of the subject/course, not something the educator sets. It affects both delivery choices and satisfaction."
    },
    {
      "name": "peer_community_presence",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "Educators can design for peer interaction/community; an intervenable lever affecting satisfaction."
    },
    {
      "name": "learner_control_over_pace",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "Whether the course is self-paced vs rigidly synchronous is a configurable design decision the educator can set."
    },
    {
      "name": "pedagogical_innovation_level",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "The degree of pedagogical innovation is an educator action/choice; intervenable lever."
    },
    {
      "name": "resource_equity_gap",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Disparity in resource access reflects the learner population/context, a common cause influencing both feasible educator interventions and satisfaction, not directly set by the educator."
    }
  ],
  "treatment_present": true,
